# ============================================================
# 工具：将 LaTeX 正文转义为 JS 模板字符串
# ============================================================
def js_escape(s):
    """将普通 LaTeX 文本转为可嵌入 JS 反引号字符串的形式。"""
    # 反斜杠双写；反引号转义；${ 转义（避免模板字符串插值）
    s = s.replace("\\", "\\\\")
    s = s.replace("`", "\\`")
    s = s.replace("${", "\\${")
    return s

